declare(strict_types=1);
/** Read-only candidate inspection: approved hashes are data, never generated by this checker. */
function paymenterUpgradeChanges(string $root, string $version, ?array $manifest = null): array
{
    $manifest ??= json_decode(file_get_contents(__DIR__.'/../data/paymenter-upgrade-hashes.json'), true, 32, JSON_THROW_ON_ERROR);
    if (!isset($manifest[$version])) { return ['missing Paymenter '.$version.' manifest -> Domains/Services/Runtime.php -> Qualify this exact release before adding support.']; }
    $release = $manifest[$version]; $known = []; $changes = [];
    $describe = static fn(string $kind, string $path, array $contract): string => $kind.' '.$path.' -> '.implode(', ', $contract['consumers']).' -> '.$contract['review'];
    foreach ($release['contracts'] as $contract) {
        foreach ($contract['files'] as $path => $hashes) {
            $known[$path] = true; $file = $root.'/'.$path;
            if (!is_file($file)) { $changes[] = $describe('missing', $path, $contract); }
            elseif (is_link($file) || !in_array(hash_file('sha256', $file), (array) $hashes, true)) { $changes[] = $describe('changed', $path, $contract); }
        }
    }
    foreach ($release['watch'] as $directory => $family) {
        $path = $root.'/'.$directory;
        if (!is_dir($path)) { continue; } // Pinned members above report removals individually.
        $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($path, FilesystemIterator::SKIP_DOTS));
        foreach ($iterator as $file) {
            $relative = substr($file->getPathname(), strlen($root) + 1);
            if ($file->getExtension() === 'php' && !isset($known[$relative])) {
                $changes[] = $describe('added', $relative, $release['contracts'][$family]);
            }
        }
    }
    sort($changes); return $changes;
}
